"""Test vectors of the 4DFX link: packets as hexadecimal text, one per line, for the firmware's host tests.

The firmware must decode every "ok" line to the listed fields, refuse every "bad" line, and build the
INFO packet of the "info" line byte for byte. `fourdvr fx test-vectors` writes this text.
"""

from __future__ import annotations

import numpy as np

from . import bridge as br


def vectors() -> str:
    lines = [
        "# 4DFX link test vectors - generated by `fourdvr fx test-vectors`; do not edit",
        "# ok <type> <node> <sequence> <packet hex> | bad <reason> <packet hex> | info <fields ...> <packet hex>",
    ]

    def ok(packet: bytes) -> None:
        ptype, node, seq, _payload = br.decode(packet)
        lines.append(f"ok {ptype} {node} {seq} {packet.hex()}")

    ok(br.build_hello(0, 1, 1_700_000_000_123_456))
    ok(br.build_hello(7, 0xFFFFFFFF, 0))
    ok(br.build_dmx(1, 2, 0, 1, bytes(range(1, 25))))
    ok(br.build_dmx(250, 3, 1, 500, bytes([255] * 13)))
    ok(br.build_dmx(1, 4, 0, 1, bytes((i * 7) % 256 for i in range(512))))
    ok(br.build_audio(1, 5, 4000, 0, (np.arange(200, dtype=np.int16) * 150 - 15000).reshape(100, 2), br.AUDIO_START))
    ok(br.build_audio(1, 6, 4000, 0xFFFFFFF0, np.array([[32767], [-32768], [0], [1]], np.int16)))
    ok(br.build_stop(1, 7, br.STOP_DMX | br.STOP_AUDIO))
    ok(br.build_stop(3, 8, br.STOP_AUDIO))
    good = br.build_dmx(1, 9, 0, 1, bytes([10, 20, 30]))
    lines.append(f"bad crc {good[:-1].hex()}{(good[-1] ^ 0x01):02x}")
    lines.append(f"bad magic {(b'4DMC' + good[4:]).hex()}")
    lines.append(f"bad version {br.encode(br.TYPE_HELLO, 0, 1, bytes(8))[:4].hex()}02{br.encode(br.TYPE_HELLO, 0, 1, bytes(8))[5:].hex()}")
    lines.append(f"bad short {good[:14].hex()}")
    lines.append(f"bad dmx-slots {br.encode(br.TYPE_DMX, 1, 10, bytes([0, 0]) + (510).to_bytes(2, 'little') + (4).to_bytes(2, 'little') + bytes(4)).hex()}")
    lines.append(f"bad dmx-length {br.encode(br.TYPE_DMX, 1, 11, bytes([0, 0]) + (1).to_bytes(2, 'little') + (4).to_bytes(2, 'little') + bytes(3)).hex()}")
    lines.append(f"bad audio-channels {br.encode(br.TYPE_AUDIO, 1, 12, bytes([3, 0]) + (4000).to_bytes(2, 'little') + bytes(4) + (2).to_bytes(2, 'little') + bytes(12)).hex()}")
    lines.append(f"bad audio-length {br.encode(br.TYPE_AUDIO, 1, 13, bytes([2, 0]) + (4000).to_bytes(2, 'little') + bytes(4) + (5).to_bytes(2, 'little') + bytes(18)).hex()}")
    lines.append(f"bad type {br.encode(0x55, 1, 14, bytes(4)).hex()}")
    info = br.NodeInfo(echo_us=1_700_000_000_123_456, uptime_ms=987654, firmware=0x0100, capabilities=br.CAP_ACTUATORS | br.CAP_DMX | br.CAP_AUDIO,
                       dmx_ports=1, audio_channels=2, state=br.STATE_DMX_ACTIVE | br.STATE_AUDIO_PLAYING, audio_rate_hz=4000,
                       audio_latency_ms=120, audio_level_ms=95, dmx_refresh_hz=40, packets=123456, invalid=3, dmx_timeouts=2,
                       audio_underruns=1, audio_gaps=4)
    fields = (info.echo_us, info.uptime_ms, info.firmware, info.capabilities, info.dmx_ports, info.audio_channels, info.state,
              info.audio_rate_hz, info.audio_latency_ms, info.audio_level_ms, info.dmx_refresh_hz, info.packets, info.invalid,
              info.dmx_timeouts, info.audio_underruns, info.audio_gaps)
    lines.append("info 5 42 " + " ".join(str(f) for f in fields) + " " + br.encode(br.TYPE_INFO, 5, 42, info.pack()).hex())
    return "\n".join(lines) + "\n"
